def test_treesitter_store_filters_uncontained_result_paths(monkeypatch, tmp_path: Path) -> None:
    repo = tmp_path / "repo"
    src = repo / "src"
    other = repo / "other"
    src.mkdir(parents=True)
    other.mkdir()
    inside = src / "inside.py"
    outside = other / "outside.py"
    external = tmp_path / "external.py"
    escape = src / "escape.py"
    inside.write_text("def inside():\n    return 1\n")
    outside.write_text("def outside():\n    return 2\n")
    external.write_text("def external():\n    return 3\n")
    try:
        escape.symlink_to(external)
    except OSError as exc:
        pytest.skip(f"platform cannot create symlink for escape-path test: {exc}")

    run_sh = tmp_path / "run.sh"
    run_sh.write_text("#!/usr/bin/env bash\n")
    captured_records = []

    def symbol(name: str) -> dict:
        return {
            "kind": "function",
            "name": name,
            "start_line": 1,
            "end_line": 2,
            "signature": f"def {name}(): ...",
        }

    class FakeClient:
        def upsert_code_symbols(self, records):
            captured_records.extend(records)
            return SimpleNamespace(
                stored=len(records),
                attempted=len(records),
                errors=[],
                stored_records=tuple(records),
            )

    def fake_run(cmd, **kwargs):
        class Result:
            returncode = 0
            stdout = json.dumps([
                {
                    "path": "inside.py",
                    "language": "python",
                    "symbols": [symbol("inside")],
                },
                {
                    "path": str(outside.resolve()),
                    "language": "python",
                    "symbols": [symbol("outside")],
                },
                {
                    "path": str(external.resolve()),
                    "language": "python",
                    "symbols": [symbol("external")],
                },
                {
                    "path": str(escape),
                    "language": "python",
                    "symbols": [symbol("escape")],
                },
            ])
            stderr = ""

        return Result()

    monkeypatch.setattr(ingest_code, "find_treesitter_skill", lambda: run_sh)
    monkeypatch.setattr(ingest_code.subprocess, "run", fake_run)
    monkeypatch.setattr(ingest_code, "CodeMemoryClient", lambda: FakeClient())

    stored = ingest_code._store_treesitter_symbols_for_directory(
        src,
        repo,
        "test",
        allowed_files=frozenset({inside.resolve(), outside.resolve(), external.resolve(), escape.resolve()}),
    )

    assert stored == 1
    assert [record.path for record in captured_records] == ["src/inside.py"]


def test_treesitter_store_rejects_scan_root_outside_codebase(monkeypatch, tmp_path: Path) -> None:
    repo = tmp_path / "repo"
    external_root = tmp_path / "external-root"
    repo.mkdir()
    external_root.mkdir()
    run_sh = tmp_path / "run.sh"
    run_sh.write_text("#!/usr/bin/env bash\n")
    subprocess_was_called = False

    def fake_run(*args, **kwargs):
        nonlocal subprocess_was_called
        subprocess_was_called = True
        raise AssertionError("Tree-sitter subprocess should not run for an out-of-codebase scan root")

    monkeypatch.setattr(ingest_code, "find_treesitter_skill", lambda: run_sh)
    monkeypatch.setattr(ingest_code.subprocess, "run", fake_run)

    with pytest.raises(ingest_code.TreeSitterScanError):
        ingest_code._store_treesitter_symbols_for_directory(
            external_root,
            repo,
            "test",
            allowed_files=frozenset(),
        )

    assert subprocess_was_called is False


@pytest.mark.parametrize("invalid_kind", ["missing", "file"])
def test_scan_rejects_invalid_codebase_before_external_work(
    invalid_kind: str,
    monkeypatch,
    tmp_path: Path,
) -> None:
    invalid_path = tmp_path / "missing"
    if invalid_kind == "file":
        invalid_path = tmp_path / "not-a-directory.py"
        invalid_path.write_text("def nope():\n    return 1\n")

    called = {
        "find_memory_skill": False,
        "load_taxonomy_module": False,
        "collect_files": False,
    }

    def fail_find_memory_skill():
        called["find_memory_skill"] = True
        raise AssertionError("memory lookup should not run for an invalid codebase")

    def fail_load_taxonomy_module():
        called["load_taxonomy_module"] = True
        raise AssertionError("taxonomy loading should not run for an invalid codebase")

    def fail_collect_files(*args, **kwargs):
        called["collect_files"] = True
        raise AssertionError("file discovery should not run for an invalid codebase")

    monkeypatch.setattr(ingest_code, "find_memory_skill", fail_find_memory_skill)
    monkeypatch.setattr(ingest_code, "load_taxonomy_module", fail_load_taxonomy_module)
    monkeypatch.setattr(ingest_code, "collect_files", fail_collect_files)

    with pytest.raises(SystemExit) as exc_info:
        ingest_code.scan(
            path=invalid_path,
            glob=[],
            cwe_only=False,
            validate=False,
            treesitter=False,
            code_index=True,
            dry_run=False,
            scope="code",
            batch_size=50,
        )

    assert exc_info.value.code == 2
    assert called == {
        "find_memory_skill": False,
        "load_taxonomy_module": False,
        "collect_files": False,
    }
    assert list(tmp_path.rglob(".ingest-code.json")) == []


def test_rescan_prevalidates_all_codebases_before_processing(monkeypatch, tmp_path: Path) -> None:
    valid_repo = tmp_path / "valid-repo"
    missing_repo = tmp_path / "missing-repo"
    valid_repo.mkdir()

    called = {
        "find_memory_skill": False,
        "load_taxonomy_module": False,
        "collect_files": False,
    }

    def fail_find_memory_skill():
        called["find_memory_skill"] = True
        raise AssertionError("memory lookup should not run before all codebases validate")

    def fail_load_taxonomy_module():
        called["load_taxonomy_module"] = True
        raise AssertionError("taxonomy loading should not run before all codebases validate")

    def fail_collect_files(*args, **kwargs):
        called["collect_files"] = True
        raise AssertionError("valid repository should not be scanned after a later invalid codebase")

    monkeypatch.setattr(ingest_code, "find_memory_skill", fail_find_memory_skill)
    monkeypatch.setattr(ingest_code, "load_taxonomy_module", fail_load_taxonomy_module)
    monkeypatch.setattr(ingest_code, "collect_files", fail_collect_files)

    with pytest.raises(SystemExit) as exc_info:
        ingest_code.rescan(
            since=None,
            validate=False,
            treesitter=False,
            code_index=True,
            verify_embeddings=False,
            scope="code",
            codebase=[str(valid_repo), str(missing_repo)],
        )

    assert exc_info.value.code == 2
    assert called == {
        "find_memory_skill": False,
        "load_taxonomy_module": False,
        "collect_files": False,
    }
    assert not (valid_repo / ".ingest-code.json").exists()


